           key:'그래서 OS 가 죽으면 <em>"커밋됐다고 판정된 것" 과 "redo 에 남은 것" 이 어긋날 수 있다</em>. 잰 값: 값 2 에서도 binlog sync 는 커밋 1,000 번에 1,000 번이다.',
