           key:'OK 를 받은 변경이 <em>OS 크래시나 전원 장애에서는 사라질 수 있다</em> — mysqld 만 죽었다면 남는다. binlog 에는 이미 커밋으로 적혀 있으므로, 사라지면 복제본과도 어긋난다.',
