           key:'커밋 때 redo 의 fsync 를 미룰 수는 있어도 <em>페이지가 redo 를 앞지르지는 못한다</em>. 이 값이 낮추는 것은 커밋의 내구성이지 WAL 의 순서가 아니다.',
